export class InFlightRequestDeduper {
    options;
    entries = new Map();
    lastCleanupTime = 0;
    constructor(options) {
        this.options = options;
    }
    get(key) {
        return this.entries.get(key);
    }
    set(key, promise, startedAt = Date.now()) {
        this.entries.set(key, { promise, startedAt });
    }
    delete(key) {
        this.entries.delete(key);
    }
    cleanup(now = Date.now()) {
        if (now - this.lastCleanupTime < this.options.cleanupIntervalMs)
            return undefined;
        this.lastCleanupTime = now;
        let cleanedCount = 0;
        for (const [key, entry] of this.entries) {
            if (now - entry.startedAt > this.options.timeoutMs) {
                this.entries.delete(key);
                cleanedCount++;
            }
        }
        if (this.entries.size > this.options.maxEntries) {
            const sorted = [...this.entries.entries()].sort((a, b) => a[1].startedAt - b[1].startedAt);
            const overflowCount = this.entries.size - this.options.maxEntries;
            for (const [key] of sorted.slice(0, overflowCount)) {
                this.entries.delete(key);
                cleanedCount++;
            }
        }
        if (cleanedCount === 0)
            return undefined;
        return {
            cleanedCount,
            remainingCount: this.entries.size,
        };
    }
}
